export function mergeReactQueryConfigs(
  a: ReactQueryConfig | undefined,
  b: ReactQueryConfig | undefined
): ReactQueryConfig {
  if (!a) {
    return b || {}
  }
  if (!b) {
    return a
  }

  const { shared: sharedA, queries: queriesA, mutations: mutationsA } = a
  const { shared: sharedB, queries: queriesB, mutations: mutationsB } = b

  return {
    shared: {
      ...(sharedA || {}),
      ...(sharedB || {}),
    },
    queries: {
      ...(queriesA || {}),
      ...(queriesB || {}),
    },
    mutations: {
      ...(mutationsA || {}),
      ...(mutationsB || {}),
    },
  }
}

